    explanation: "【要点】ACPは、多くの2型糖尿病成人でHbA1c 7〜8%を目標とし、<6.5%のような過度に厳格な管理は避けるべきと提言している(de-emphasis)。\n【背景】ACCORD等で厳格管理が低血糖・死亡リスクを増やす一方、大血管イベントを明確に減らさなかったことを踏まえる。近年の更新では、SGLT2阻害薬・GLP-1受容体作動薬を臓器保護目的で治療選択に加えることも支持している。\n【臨床応用】平均余命が限られる・併存症の多い高齢者ではさらに緩やかな目標とし、低血糖回避を優先。目標は個別化する。\n【誤答】全例<6.5%や高齢者での厳格化は低血糖・過剰治療の観点で不適切。目標の放棄も誤り。",
