    explanation: "【要点】顕性甲状腺機能低下症はTSH高値+fT4低値で診断し、レボチロキシン(LT4)単剤で補充するのが標準(Lancet)。\n【背景/エビデンス】原因は橋本病が多い。LT4は半減期が長く1日1回・空腹時服用が基本。開始量は年齢・心疾患・重症度で調整し、TSHを目安に6〜8週ごとに用量を漸増する。\n【臨床応用】過少・過剰補充はいずれも心血管・代謝リスクとなるため、TSHを目標域に保つ。無症候の一般成人へのルーチンTSHスクリーニングはUSPSTFで根拠不十分とされる。\n【誤答】『TSH低値+fT4高値』は機能亢進の所見で誤り。T3含有製剤は第一選択でなく、全員スクリーニングも推奨されない。",
