    explanation: "【要点】SURMOUNT-5は、糖尿病のない肥満成人でチルゼパチド(GIP/GLP-1)がセマグルチドより有意に大きい減量を示した初の直接比較試験。\n【エビデンス】751例を最大耐用量(チルゼパチド10/15mg、セマグルチド1.7/2.4mg)に無作為化し72週。平均体重変化は−20.2% vs −13.7%(約22.8kg vs 15.0kg)、腹囲も−18.4cm vs −13.0cmでチルゼパチドが優越した。消化器有害事象による中止はセマグルチド5.6% vs チルゼパチド2.7%。\n【臨床応用】減量幅を重視する場面ではチルゼパチドが選択肢だが、費用・供給・忍容性・アウトカムの蓄積度も踏まえ個別化する。\n【誤答】同等・セマグルチド優越・臨床的無効は、いずれも試験結果と異なる。",
