    options: ["アルドステロンを抑制するため高カリウム血症のモニタリングが必要で、コントロール不良/抵抗性高血圧の収縮期血圧を有意に低下させた", "主にコルチゾール合成を阻害するためグルココルチコイド補充が必須である", "血圧低下は得られたが低カリウム血症が問題となった", "ミネラルコルチコイド受容体を遮断する点でスピロノラクトンと同一機序である"],
