    explanation: "【要点】バクスドロスタットはアルドステロン合成酵素(CYP11B2)を選択的に阻害する新規降圧薬で、BaxHTN試験でコントロール不良/治療抵抗性高血圧の収縮期血圧を有意に低下させた。アルドステロン抑制に伴う高カリウム血症のモニタリングが必要。\n【背景/エビデンス】標準治療への上乗せで、プラセボ補正でおよそ収縮期9〜10mmHgの低下(2mgで24時間SBPを約17mmHg低下)。2025年ESCで発表されNEJMに同時掲載された。CYP11B1(コルチゾール)への選択性が高く、副腎不全は起こしにくい設計。\n【臨床応用/注意】導入後はカリウム・ナトリウムと腎機能をモニタリングする。\n【誤答】機序はMR遮断(スピロノラクトン)ではなく合成阻害であり、コルチゾール阻害主体でもなく、注意すべきは低Kではなく高Kである。",
    source: { title: "Baxdrostat and the future of aldosterone-targeted therapy (Hypertension Research 2025)", url: "https://www.nature.com/articles/s41440-025-02415-5" },
    tags: ["高血圧", "治療抵抗性", "バクスドロスタット", "アルドステロン合成酵素"]
