    explanation: "【要点】SIADHは低張性・等容量性の低ナトリウム血症で、血清浸透圧低下下にもかかわらず尿浸透圧>100 mOsm/kg・尿中Na>40 mEq/Lを示す。無症候〜軽症例の初期治療は水制限が基本。\n【背景/エビデンス】診断には甲状腺・副腎機能の正常確認と、利尿薬使用・嘔吐/下痢など他要因の除外を要する。小細胞肺癌・中枢神経疾患・薬剤(SSRI・カルバマゼピン等)が原因となる。\n【臨床応用/注意】重症・症候性(痙攣・意識障害)では高張食塩水を慎重に用いるが、補正は緩徐に(概ね24時間で8〜10 mEq/L以内)行い浸透圧性脱髄を避ける。\n【誤答】尿浸透圧<100が要件・甲状腺副腎評価不要・無症候例への高張食塩水急速静注は、いずれも不適切。",
