    explanation: "【要点】SUMMIT試験では、肥満を伴うHFpEF患者に対する週1回のチルゼパチドが、心不全増悪イベント(心血管死または心不全悪化)のリスクを有意に低下させ、健康状態や運動耐容能も改善した。\n【背景/エビデンス】NEJM(2024年発表)。約2年間の投与で、GIP/GLP-1受容体作動薬であるチルゼパチドがKCCQスコアの改善、体重減少、左室心筋重量や心臓周囲脂肪の減少を示した。STEP-HFpEF(セマグルチド)に続き、肥満HFpEFにインクレチン関連薬が有益であることを支持する。\n【臨床応用/注意】悪心・嘔吐・下痢などの消化器症状に注意し漸増する。肥満HFpEFという表現型に対する疾患修飾的アプローチとして位置づけられつつある。\n【誤答】イベント増加・変化なし・心不全指標の悪化は、いずれも試験結果と異なる。",
