    explanation: "【要点】JAS2022では二次予防のLDL-C目標は原則<100 mg/dLだが、急性冠症候群・家族性高コレステロール血症・糖尿病・冠動脈疾患とアテローム血栓性脳梗塞の合併を伴う場合は<70 mg/dLとより厳格に管理する。\n【背景/エビデンス】2022年版は二次予防の対象に冠動脈疾患に加えアテローム血栓性脳梗塞を追加した。高リスク病態でLDL-Cを一段低い目標へ下げることで再発リスク低減が期待される。一次予防のリスク層別には吹田スコア等に基づく絶対リスク評価を用いる。\n【臨床応用/注意】高強度スタチンを基本とし、目標未達ならエゼチミブ、さらにPCSK9阻害薬を追加する。目標値は一律でなく病態の重症度で個別化する。\n【誤答】安定高血圧のみの冠動脈疾患や非アテローム血栓性脳梗塞、低リスク一次予防は<70 mg/dLの対象として明示されておらず、それぞれ<100 mg/dLや別のカテゴリー目標が適用される。",
