    correct: 1,
    explanation: "【要点】メトホルミンは重度腎機能障害(eGFR<30)が禁忌で、eGFR30〜45は慎重投与としてリスクとベネフィットを勘案する。\n【背景/エビデンス】日本糖尿病学会『メトホルミンの適正使用に関するRecommendation』および添付文書改訂で、腎機能を理由とする禁忌はeGFR<30に限定された。乳酸アシドーシスは腎障害・脱水・シックデイ・過度の飲酒・高齢・肝障害・心肺機能低下などで生じやすい。\n【臨床応用/注意】シックデイや脱水時、ヨード造影剤使用の前後は一時中止し、腎機能の回復を確認して再開する。高齢者ではeGFRだけでなく全身状態も評価する。\n【誤答】eGFR60未満で一律禁忌ではない。腎機能正常でも脱水等で乳酸アシドーシスは起こりうる。造影剤使用時は中止が必要で継続は不適切。",
