    correct: [0, 2, 3],
    explanation: "【要点】サルコイドーシスの臨床診断では、血清ACE/リゾチーム高値、BALでのリンパ球増多とCD4/CD8比>3.5、67Gaシンチや18F-FDG-PETでの著明な集積などの特徴的所見を組み合わせる。\n【背景/エビデンス】非乾酪性類上皮細胞肉芽腫が病理学的特徴で、両側肺門リンパ節腫脹(BHL)、ぶどう膜炎、血清sIL-2R高値なども診断を支持する。心臓・眼・神経病変は予後に影響する。\n【臨床応用/注意】無症候のBHLは経過観察も選択肢だが、心・眼・神経病変や高カルシウム血症を伴う活動性病変ではステロイドを検討する。心サルコイドーシスはFDG-PETやMRIで評価する。\n【誤答】MPO-ANCA高値は顕微鏡的多発血管炎等でみられ、サルコイドーシスの特徴的診断所見ではない。",
