    options: ["NOAC単剤は併用療法に非劣性で、正味の有害臨床イベントはむしろ少なかった", "NOAC単剤は併用療法より正味の有害臨床イベントが有意に多かった", "併用療法は出血を増やさず虚血イベントを有意に減らした", "両群で有効性・安全性に差はなく結論は得られなかった"],
    correct: 0,
    explanation: "【要点】DES留置後1年以上を経た心房細動患者では、NOAC単剤が『NOAC+クロピドグレル併用』に対し正味の有害臨床イベントで非劣性であり、イベントはむしろ少なかった。\n【背景/エビデンス】NEJM2025、韓国32施設の非盲検RCT(約960例、平均71歳)。主要評価は総死亡・心筋梗塞・ステント血栓症・脳卒中・全身塞栓・大出血/臨床的に重要な出血の複合。単剤群9.6%対併用群17.2%(HR0.54)と単剤が優れた。\n【臨床応用/注意】安定した慢性冠動脈疾患を合併するAFでは、抗血小板薬を上乗せせず抗凝固単剤とする方針を支持する。急性期や高血栓リスク例では個別判断が必要。\n【誤答】単剤が有意に多い、併用が虚血を有意に減らす、差がなく結論不能、はいずれも試験結果と異なる。",
