    explanation: "【要点】糖尿病を伴わないCKDでも、標準治療へのフィネレノン上乗せは主要評価項目であるeGFR低下速度(slope)を有意に改善した。\n【背景/エビデンス】非ステロイド型ミネラルコルチコイド受容体拮抗薬フィネレノンの第III相FIND-CKD。1,500例超の非糖尿病CKD(高血圧性腎症や糸球体疾患等)を対象に、最大耐用量のRAS阻害薬を含む標準治療へ上乗せし、ベースラインから32か月のeGFR年間変化を主要評価とした。\n【臨床応用/注意】従来フィネレノンのエビデンスは2型糖尿病合併CKDが中心だったが、非糖尿病CKDへの適応拡大が期待される。導入時は血清カリウムと腎機能の監視が必要。\n【誤答】eGFRがプラセボ同等、総死亡の有意減少、高カリウムで早期中止、はいずれも本試験の主要結果と異なる。",
    source: { title: "KERENDIA (finerenone) Meets Primary Endpoint in Phase III FIND-CKD Study (Bayer)", url: "https://www.bayer.com/en/us/news-stories/kerendia-for-non-diabetic-chronic-kidney-disease" },
    tags: ["腎臓", "CKD", "フィネレノン", "非糖尿病"]
